const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sonoran Desert region (approximate bounds)
  const sonoran = ee.Geometry.Polygon([
    [[-116, 27], [-116, 34], [-108, 34], [-108, 27], [-116, 27]]
  ]);

  // 2. Load MODIS LST data for 2019
  const lstCollection = ee.ImageCollection('MODIS/006/MOD11A2')
    .filterDate('2019-01-01', '2019-12-31')
    .filterBounds(sonoran)
    .select('LST_Day_1km');

  const collectionSize = lstCollection.size().getInfo();
  console.log('Collection size:', collectionSize);

  if (collectionSize === 0) {
    console.log('No MODIS LST data found for Sonoran Desert in 2019.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Convert from Kelvin (scaled by 0.02) to Celsius and find maximum
  const lstCelsius = lstCollection.map(function(img) {
    return img.multiply(0.02).subtract(273.15).copyProperties(img, ['system:time_start']);
  });

  // 4. Get maximum temperature across all images
  const maxLST = lstCelsius.max();

  // 5. Check if any pixels exceed 75°C
  const stats = maxLST.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sonoran,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTemp = stats['LST_Day_1km_max'];
  const pixelCount = stats['LST_Day_1km_count'];

  console.log('Images in collection:', collectionSize);
  console.log('Valid pixels analyzed:', pixelCount);
  console.log('Maximum temperature found (°C):', maxTemp ? maxTemp.toFixed(2) : 'null');

  // 6. Validation and answer
  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (maxTemp === null || maxTemp === undefined || isNaN(maxTemp)) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxTemp < -100 || maxTemp > 100) {
    console.log('Temperature out of realistic range.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxTemp > 75) {
    console.log('Temperature exceeded 75°C threshold.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Temperature did not exceed 75°C threshold.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
